# AWS side of the CI handover for the platform/ingest GitHub Actions workflow.
#
# Two roles, split by trust:
#   - plan  : assumable from pull requests, read-only on managed resources
#   - apply : assumable only from the main branch, can change managed resources
#
# Note: an account can hold only one OIDC provider per issuer URL. If
# token.actions.githubusercontent.com already exists in this account, import it
# instead of creating it.

locals {
  github_repo = "platform/ingest"

  state_bucket = "ingest-terraform-state"
  state_key    = "ingest/terraform.tfstate"

  landing_bucket_arn = "arn:aws:s3:::ingest-landing-staging"
  events_queue_arn   = "arn:aws:sqs:eu-north-1:${data.aws_caller_identity.current.account_id}:ingest-events-staging"
  checkpoints_arn    = "arn:aws:dynamodb:eu-north-1:${data.aws_caller_identity.current.account_id}:table/ingest-checkpoints-staging"
}

data "aws_caller_identity" "current" {}

resource "aws_iam_openid_connect_provider" "github" {
  url            = "https://token.actions.githubusercontent.com"
  client_id_list = ["sts.amazonaws.com"]
}

data "aws_iam_policy_document" "plan_trust" {
  statement {
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = [aws_iam_openid_connect_provider.github.arn]
    }

    condition {
      test     = "StringEquals"
      variable = "token.actions.githubusercontent.com:aud"
      values   = ["sts.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "token.actions.githubusercontent.com:sub"
      values   = ["repo:${local.github_repo}:pull_request"]
    }
  }
}

data "aws_iam_policy_document" "apply_trust" {
  statement {
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = [aws_iam_openid_connect_provider.github.arn]
    }

    condition {
      test     = "StringEquals"
      variable = "token.actions.githubusercontent.com:aud"
      values   = ["sts.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "token.actions.githubusercontent.com:sub"
      values   = ["repo:${local.github_repo}:ref:refs/heads/main"]
    }
  }
}

resource "aws_iam_role" "plan" {
  name                 = "ingest-ci-plan"
  assume_role_policy   = data.aws_iam_policy_document.plan_trust.json
  max_session_duration = 3600
}

resource "aws_iam_role" "apply" {
  name                 = "ingest-ci-apply"
  assume_role_policy   = data.aws_iam_policy_document.apply_trust.json
  max_session_duration = 3600
}

# --- Terraform state access ---------------------------------------------------

data "aws_iam_policy_document" "state_read" {
  statement {
    sid       = "ListStateBucket"
    actions   = ["s3:ListBucket"]
    resources = ["arn:aws:s3:::${local.state_bucket}"]
  }

  statement {
    sid       = "ReadState"
    actions   = ["s3:GetObject"]
    resources = ["arn:aws:s3:::${local.state_bucket}/${local.state_key}"]
  }

  # use_lockfile = true: plan still takes the lock, which is a sibling object.
  statement {
    sid       = "StateLockfile"
    actions   = ["s3:GetObject", "s3:PutObject", "s3:DeleteObject"]
    resources = ["arn:aws:s3:::${local.state_bucket}/${local.state_key}.tflock"]
  }
}

data "aws_iam_policy_document" "state_write" {
  statement {
    sid       = "WriteState"
    actions   = ["s3:PutObject"]
    resources = ["arn:aws:s3:::${local.state_bucket}/${local.state_key}"]
  }
}

# --- Read-only access to the managed resources (plan) -------------------------

data "aws_iam_policy_document" "plan" {
  source_policy_documents = [data.aws_iam_policy_document.state_read.json]

  statement {
    sid       = "ReadLandingBucket"
    actions   = ["s3:GetBucket*", "s3:GetLifecycleConfiguration", "s3:GetEncryptionConfiguration", "s3:GetAccelerateConfiguration", "s3:GetReplicationConfiguration", "s3:ListBucket"]
    resources = [local.landing_bucket_arn]
  }

  statement {
    sid       = "ReadEventsQueue"
    actions   = ["sqs:GetQueueAttributes", "sqs:GetQueueUrl", "sqs:ListQueueTags"]
    resources = [local.events_queue_arn]
  }

  statement {
    sid       = "ReadCheckpointsTable"
    actions   = ["dynamodb:DescribeTable", "dynamodb:DescribeContinuousBackups", "dynamodb:DescribeTimeToLive", "dynamodb:ListTagsOfResource"]
    resources = [local.checkpoints_arn]
  }

  statement {
    sid       = "ReadCallerContext"
    actions   = ["sqs:ListQueues", "iam:GetOpenIDConnectProvider", "iam:GetRole", "iam:ListRolePolicies", "iam:ListAttachedRolePolicies", "iam:GetRolePolicy"]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "plan" {
  name   = "terraform-plan"
  role   = aws_iam_role.plan.id
  policy = data.aws_iam_policy_document.plan.json
}

# --- Change access to the managed resources (apply) ---------------------------

data "aws_iam_policy_document" "apply" {
  source_policy_documents = [
    data.aws_iam_policy_document.plan.json,
    data.aws_iam_policy_document.state_write.json,
  ]

  # Bucket-level only: no s3:*Object on the landing data.
  statement {
    sid = "ManageLandingBucket"
    actions = [
      "s3:CreateBucket",
      "s3:DeleteBucket",
      "s3:PutBucket*",
      "s3:PutLifecycleConfiguration",
      "s3:PutEncryptionConfiguration",
      "s3:PutAccelerateConfiguration",
      "s3:PutReplicationConfiguration",
      "s3:DeleteBucketPolicy",
    ]
    resources = [local.landing_bucket_arn]
  }

  statement {
    sid = "ManageEventsQueue"
    actions = [
      "sqs:CreateQueue",
      "sqs:DeleteQueue",
      "sqs:SetQueueAttributes",
      "sqs:TagQueue",
      "sqs:UntagQueue",
    ]
    resources = [local.events_queue_arn]
  }

  statement {
    sid = "ManageCheckpointsTable"
    actions = [
      "dynamodb:CreateTable",
      "dynamodb:DeleteTable",
      "dynamodb:UpdateTable",
      "dynamodb:UpdateContinuousBackups",
      "dynamodb:UpdateTimeToLive",
      "dynamodb:TagResource",
      "dynamodb:UntagResource",
    ]
    resources = [local.checkpoints_arn]
  }
}

resource "aws_iam_role_policy" "apply" {
  name   = "terraform-apply"
  role   = aws_iam_role.apply.id
  policy = data.aws_iam_policy_document.apply.json
}

output "ci_plan_role_arn" {
  description = "Role for the workflow's plan job (pull requests)."
  value       = aws_iam_role.plan.arn
}

output "ci_apply_role_arn" {
  description = "Role for the workflow's apply job (main only)."
  value       = aws_iam_role.apply.arn
}

